"events.faceplant_got_tired_of_korean_usage":"Faceplant가 한국의 망 사용료에 지쳐서 한국 사용자를 슬쩍 홍콩 서버로 옮겼어요. 서울에서는 누구든 페이지가 기어 다니듯 느리게 떠요. 규제 당국이 과징금을 준비하고 있어요.",
"events.faceplant_rerouted_korea_via_hong":"<b>Faceplant가 한국 트래픽을 홍콩으로 우회시켰어요.</b><br>어떻게 연결하든 20일간 서울 사용자가 받는 양이 5분의 1 줄어요.",
"events.glitch_is_leaving_korea_the_game":"<b>Glitch가 한국에서 철수해요.</b><br>이 게임 스트리밍 사이트는 한국의 망 사용료가 “감당할 수 없을 만큼 비싸다”며 한국 서비스를 종료해요. 서울 트래픽이 영구적으로 절반으로 줄어요. 국내 스트리머들은 이미 다른 데로 옮겼어요.",
"events.golden_week_demand_in_mainland_china":"<b>황금연휴!</b><br>일주일 동안 중국 본토의 수요가 40% 늘어요.",
"events.landing_permit_dispute_in_city_two":"<b>{city} 육양 허가 분쟁</b><br>두 부처가 서로 해변이 자기 관할이라고 해요. 45일 동안 새 해저 링크를 육양할 수 없어요.",
"events.name_hits_city_power_is_out":"<b>{name}, {city} 강타</b><br>정전으로 POP가 이틀 동안 꺼져요. 발전기가 있었다면 살렸을 거예요.",
"events.name_hits_city_the_grid_is":"<b>{name}, {city} 강타</b><br>전력망이 나갔지만 비상 발전기 덕분에 라우터는 계속 돌아갔어요.",
"events.name_knocked_out_power_in_city":"{name} 때문에 {city}에 정전이 났어요. POP에 발전기가 없어요.",
"events.new_season_of_stranger_pings_just":"<b>“기묘한 핑 이야기” 새 시즌 공개!</b><br>일주일 동안 개인 사용자 수요가 25% 늘어요. 여유 용량 있으세요?",
"events.optical_control_plane_meltdown_every":"<b>광 컨트롤 플레인 붕괴!</b><br>{reg}의 임대 파장이 한꺼번에 전부 꺼졌어요. 자체 다크 파이버는 멀쩡해요. 이래서 다들 광섬유를 직접 소유하는 거예요.",
