"events.peering_spat_cogentle_de_peered":"<b>피어링 분쟁!</b><br>Cogentle이 20일 동안 Goggle과의 피어링을 끊었어요. Cogentle 트랜짓을 타던 Goggle 트래픽이 사라졌어요. Goggle과 직접 피어링하거나 다른 업스트림을 쓰세요.",
