"events.rural_broadband_grant_30k_the":"<b>농촌 브로드밴드 보조금: +$30k</b><br>Ministry of Tubes가 지금 하는 일을 마음에 들어 해요.",
"events.sanctions_the_republic_of":"<b>제재!</b><br>Republic of Red Tape가 라우터 벤더가 애용하는 나사 공급업체를 제재했어요. 예비 부품이 늦게 와서 60일 동안 라우터 고장 수리가 2배 오래 걸려요.",
