"glowball_sakura_lager.on_tap_in_the_big_hubs":"미국, 유럽, 아시아·태평양의 주요 허브에서 생맥주로 판매 중. 세 개의 Tier 1 케그에서 따른 트랜짓을 재판매하고, PNI를 받으며, 어디서든 개방적으로 피어링해요. 본고장에서 멀어지면 한 잔 값이 올라가고, 호주 사람에게는 한 방울도 따라 주지 않아요. 자신은 Tier 1이 아니고, 청구서의 벚꽃은 순전히 장식이에요.",
"goals.5_pops_ports_on_3_ixs":"POP 5개 이상, IX 3곳 이상에 포트, 피어링 세션 15개 이상.",
