"goals.a_terabit_per_second_of_happy":"행복한 트래픽 초당 1테라비트.",
"goals.add_a_second_site_in_a":"인프라 탭에서 대도시에 두 번째 사이트를 추가하세요. 정전 한 번에 도시 전체가 깜깜해지는 일이 없어져요.",
"goals.be_in_two_buildings_at_once":"두 건물에 동시에 존재하기",
"goals.become_a_tier_2":"Tier 2 되기",
"goals.big_cdns_give_you_free_cache":"대형 CDN은 트래픽을 충분히 보내 주면 캐시 박스를 무료로 줘요. 공짜 대역폭, 전기만 꽂으면 끝.",
"goals.build_a_scrubbing_center_from_a":"POP의 인프라 탭에서 스크러빙 센터를 지으세요. 용량만큼 공격을 정화하고 DDoS 방어 상품도 팔 수 있어요.",
"goals.businesses_show_up_with_a_bubble":"기업은 $ 말풍선과 함께 나타나요. 그 도시에 POP이 있어야 해요. 거래 탭을 확인하세요.",
"goals.drag_from_your_pink_router_to":"분홍색 라우터에서 다른 도시로 드래그하세요. 짧은 구간은 싸요. 바다는 아니고요.",
"goals.get_a_port_at_an_ix":"IX에 포트를 확보하세요. 여러 네트워크가 트랜짓 비용 없이 무료로 트래픽을 주고받는 거대한 공유 스위치예요.",
"goals.have_pops_on_3_continents_subsea":"3개 대륙에 POP 두기. 해저 케이블은 엄청 비싸니 경로를 잘 계획하세요.",
