"goals.land_an_ai_wan_a_multi":"하이퍼스케일러의 AI WAN, 다중 사이트 학습 실행, 광섬유 페어 거래 중 하나를 따내세요. 고객 레벨 4와 캠퍼스 근처 POP이 필요해요.",
