"goals.lease_or_dig_dark_fiber_put":"다크 파이버를 임대하거나 직접 파서 DWDM 시스템을 올리고 채널을 켜세요. 일단 돌아가기만 하면 비트당 비용이 파장 서비스보다 싸요.",
