"goals.on_the_peering_tab_request_sessions":"피어링 탭에서 세션을 요청하거나, 라우트 서버에 가입해 모든 개방형 네트워크와 한 번에 피어링하세요.",
"goals.open_your_home_city_and_press":"본거지 도시를 열고 “브로드밴드 출시”를 누르세요. 개인 사용자는 집에서 고양이 동영상을 보는 사람들이에요. 매달 돈을 내 줘요.",
"goals.outcast_found_an_ix":"공용 IX는 출입 금지예요. IX가 없는 도시에 직접 IX를 세우면 네트워크들이 가입할 거예요.",
