"goals.peer_with_every_tier_1_their_customers":"모든 Tier 1과 PNI로 피어링하고 트랜짓 포트를 전부 해지하세요. 그들의 고객은 덤으로 따라오니, 아무도 트랜짓을 팔지 않는 네트워크만 쫓으면 돼요.",
