"hyper_dir.held":"🧊 {city}은(는) 빌린 장비로 밤을 버텼어요. {util}이(가) 안부 전해 달래요.",
"hyper_dir.intro_ai":"🧠 <b>AI 연구소들이 연락처를 알아냈어요.</b> 내 리전 두 곳 사이에서 몇 주짜리 학습을 원해요. 제때 끝내면 수백만, 늦으면 절반이에요.",
"hyper_dir.intro_ddos":"🧨 <b>봇넷이 주소를 알아냈어요.</b> 가끔 누군가 테넌트에게 트래픽을 퍼부어요. 남는 포트와 넉넉한 백본이 흡수해 줘요.",
"hyper_dir.intro_fail":"🦍 <b>리전이 두 개니, 이제 리전 하나가 통째로 죽을 수도 있어요.</b> 그러면 사용자는 복제 리전으로 옮겨 가요. 백로그는 낮게, 백본은 넓게 유지하세요: 이게 시험이에요.",
"hyper_dir.intro_freeze":"🎮 <b>게임 스튜디오가 출시를 준비 중이에요.</b> 출시일엔 트래픽이 몇 배로 뛰고 네트워크 변경이 동결되니, 동결 전에 지어 두세요.",
"hyper_dir.intro_inc":"☁️ <b>이제 클라우드다운 방식으로 고장 날 만큼 커졌어요.</b> 만료된 인증서, 복제 폭주, 점 하나 빠진 Route 66. 각각 수리 버튼이 함께 와요.",
"hyper_dir.intro_law":"🏛️ <b>규제 당국이 클라우드를 발견했어요.</b> 법은 유예 기간을 두고 와요: 요구하는 곳에 짓거나, 돈을 내세요.",
"hyper_dir.intro_pev":"⚡ <b>이제 전력에도 기분이 있어요.</b> 폭염과 에너지 위기가 대륙 전체를 덮쳐요: 요금은 오르고 냉각기는 진땀을 흘려요. 전력망이 끊기기 직전이면 하루 전에 경고가 와요.",
"hyper_dir.intro_rv":"🥊 <b>경쟁 클라우드가 눈치챘어요.</b> 테넌트에게 입찰하고, 갱신 때 불만 있는 고객에게 추파를 던지고, 가끔은 가격 전쟁도 시작할 거예요.",
