"hyper_ops.o_az":"리전에 존 추가",
"hyper_ops.o_az_d":"국지 장애(크래시, 정전, 건물 하나에서의 손가락 실수)를 겪은 리전에 가용 영역을 하나 더 만들어요. 레벨, 메가와트, 법이 허락하는 경우에만요. 근무 한 번에 하나.",
"hyper_ops.o_drill":"페일오버 훈련",
"hyper_ops.o_drill_d":"가장 오래전에 훈련한 리전 쌍(한 번도 안 한 쌍이 먼저)을 한 번에 하나씩 훈련해요. 출시 동결 직전에는 절대 안 해요.",
"hyper_ops.o_fund":"시위 대응",
"hyper_ops.o_fund_d":"지역 기금으로 설득할 수 있는 시위에는, 아래 금액 한도 안에서 설득될 때까지 기금을 내요. 호감도로 트래픽이 옮겨지진 않아요.",
"hyper_ops.o_rg":"리전 감시",
"hyper_ops.o_rg_desc":"기준선 이상인 리전은 다음 등급으로 올려요. 최대 한 달에 한 번, 두 레벨 전에 도달한 등급까지만, 메가와트와 법이 허락하고 그달이 흑자로 유지될 때만요. 전력이 부족하면 전력 회사에 미리 요청해요. 그 밖에는 보고서에 메모만 남겨요.",
"hyper_ops.o_wave":"백로그용 파장",
"hyper_ops.o_wave_desc":"복제 백로그가 기준선을 넘어 커지는 리전 쌍에는 두 리전 사이에 파장을 임대해요. 모자랐던 만큼을 나를 수 있는 가장 작은 걸로요. 근무 한 번에 하나, 그다음 일주일은 백로그가 빠지길 기다려요. 월 요금은 예산에서 차감되고, 그달을 적자로 만들지는 않아요.",
