"hyper_reg.pue_n":{"one":"리전 하나가 열을 버리고 있어요: 뭔가를 데울 때까지 MW당 매달 {fee}.","other":"리전 {n}개가 열을 버리고 있어요: 뭔가를 데울 때까지 MW당 매달 {fee}."},
"hyper_reg.title":"규제 당국",
"hyper_resale.ask_forever":"인턴: '{a}–{b} 구간 {name}와(과)의 남는 페어 썸, 제 학자금 대출보다 오래 가요. 그래도 확실해요?'",
"hyper_resale.ask_mum":"인턴: '엄마가 {a}–{b} 구간 {name}와(과)의 남는 페어 썸에 대해 물어보셨어요. 확실하시다고 했는데, 맞죠?'",
"hyper_resale.ask_photons":"인턴: '{a}–{b} 구간 {name}와(과)의 남는 페어 썸, 확실해요? 그 광자들이 필요해지면요?'",
"hyper_resale.ask_sure":"인턴: '{a}–{b} 구간 {name}와(과)의 남는 페어 썸 말인데요… 확실해요? 진짜 확실해요?'",
"hyper_resale.card_sold":{"one":"{desk}: 판매 {n}건, {price}/월 (레벨에는 절대 반영 안 됨)","other":"{desk}: 판매 {n}건, {price}/월 (레벨에는 절대 반영 안 됨)"},
"hyper_resale.declined":"{desk}은(는) 다른 곳에 전화할 거예요.",
"hyper_resale.lead":"가끔 통신사가 이 구간의 남는 페어(IRU: 선불 일시금에 유지보수용 소액 월 요금)나 내 라인 시스템의 파장 서비스를 사려고 데스크에 전화해요. 판 만큼은 이 구간에서 내 복제와 학습에 못 써요.",
"hyper_resale.leased_lead":"임대한 광섬유는 되팔 수 없어요. 직접 지은 광섬유만 팔 수 있어요: 남는 페어나 파장 서비스로요.",
"hyper_resale.no_room_wave":"오늘 밤 이 광섬유에는 {g} 파장을 넣을 자리가 없어요.",
"hyper_resale.no_spare_pair":"이 광섬유에는 남는 페어가 없어요.",
"hyper_resale.not_levels":"재판매 수익은 레벨, 목표, 클라우드 나인에 절대 반영되지 않아요.",
"hyper_resale.not_yours":"직접 지은 광섬유만 되팔 수 있어요.",
"hyper_resale.offer":"{desk}: {name}이(가) {what}을(를) {price}/월에 원해요.",
"hyper_resale.offer_line":"{name}: {what}, {price}/월",
"hyper_resale.offer_up":"선불 {up} 추가.",
"hyper_resale.pair_sold":"이 페어는 IRU로 팔렸어요: 점등은 통신사 몫이지 내 몫이 아니에요.",
"hyper_resale.sold_pair":"{a}–{b} 남는 페어를 {name}에게 팔았어요: 선불 {up}, 이후 {price}/월. 남는 페어 썸이 공식 연애가 됐어요.",
"hyper_resale.sold_wave":"{a}–{b} {g} 파장을 {name}에게 {price}/월에 팔았어요. 그 구간의 내 트래픽에는 이제 못 써요.",
