"hyper_rivals.card_calm":"경쟁사가 맴돌지만 경합 중인 건 없음",
"hyper_rivals.card_contested":{"one":"경합 중인 제안 {n}건","other":"경합 중인 제안 {n}건"},
"hyper_rivals.card_down":"{rival}, {date}까지 {reg}에서 다운: 이탈 고객 연락 중",
"hyper_rivals.card_tally":"경쟁사에 {lt} 빼앗김, {bt} 지켜 냄",
