"hyper_rivals.courting":"🥊 {rival}이(가) {date}에 계약이 끝나는 {name}에게 추파를 던지고 있어요. 그때까지 만족도를 {p}% 넘게 올리지 않으면 떠나요.",
"hyper_rivals.down_cert":"아무도 갱신하지 않은 인증서 하나가 {reg}의 {rival}을(를) 다운시켰어요. 그쪽 테넌트들이 나한테 전화하고 있어요.",
"hyper_rivals.down_dns":"DNS 레코드 하나 때문에 {reg} 전역에서 {rival}이(가) 다운됐어요. 그쪽 테넌트들이 나한테 전화하고 있어요.",
"hyper_rivals.down_status":"{rival}의 {reg} 상태 페이지는 전부 초록색이에요. 나머지는 다 불타고 있고요. 그쪽 테넌트들이 나한테 전화하고 있어요.",
"hyper_rivals.down_typo":"{reg}에서 {rival}이(가) 다운됐어요: 정기 점검 중에 누가 명령어를 잘못 쳤대요. 그쪽 테넌트들이 나한테 전화하고 있어요.",
"hyper_rivals.ignored_war":"{rival}이(가) {reg}에서 시작한 가격 전쟁을 무시해요. 용감하네요.",
"hyper_rivals.ignoring":"무시함",
"hyper_rivals.job_coupon":"{lab}은(는) 학습 작업을 {rival}에게 맡겼어요. 다음 작업 10% 할인 쿠폰도 받았대요.",
"hyper_rivals.job_gpus":"{rival}이(가) {lab}의 학습 작업을 가져갔어요: '저희 GPU 있어요. 음, 곧 생길 거예요.'",
"hyper_rivals.job_thinking":"고민하는 사이에 {rival}이(가) {lab}의 학습 작업을 가져갔어요.",
"hyper_rivals.job_wait":"기다리면 {date}에 {rival}이(가) 이 작업을 가져가요.",
