"lifecycle.odd_bought_thrice":"그들을 인수한 회사를 인수한 회사가 이미 네트워크를 갖고 있대요. 누가 책임자인지 아무도 몰라요.",
"lifecycle.odd_center":"지연 시간이 중요하다는 글을 읽고 인터넷의 중심 가까이로 이사한대요. 그게 시골 어느 들판에 있다고 믿고 있어요.",
"lifecycle.odd_communities":"BGP 커뮤니티 문서가 더 잘 정리된 공급자로 옮겼어요. 문서화된 커뮤니티는 딱 두 개예요.",
"lifecycle.odd_dead_beef":"16진수로 회사 이름이 써지는 IPv6 주소를 원했는데, :dead:beef는 이미 누가 가져갔어요.",
"lifecycle.odd_espresso":"사무실에 새로 들인 에스프레소 머신이 차단기를 내려요. 라우터 탓을 하니, 결국 우리 탓이래요.",
"lifecycle.odd_fewer_vendors":"새 CEO가 공급업체를 줄이고 싶어 해요. 우리가 유일한 업체였어요. 이제 하나도 없는데, 아주 만족해해요.",
"lifecycle.odd_goat_farmer":"우리와 계약했던 담당자가 염소 농부가 되겠다며 떠났고, 후임자는 일하는 방식이 달라요.",
"lifecycle.odd_holiday_card":"연말 카드가 제때 도착했어요. 그게 오히려 수상해 보였대요.",
"lifecycle.odd_landlord":"건물주가 벽을 통과하는 케이블마다 요금을 받는데, 우리 케이블은 두껍고 너무 눈에 띄어요.",
"lifecycle.odd_looking_glass":"루킹 글래스가 한 시간 동안 다운됐는데, 그쪽 NOC 리더가 그걸 개인적인 모욕으로 받아들였어요.",
"lifecycle.odd_mate":"우리 영업 담당자가 이메일에서 그쪽 담당자를 '친구'라고 불렀어요. 둘은 친구가 아니에요.",
"lifecycle.odd_quadrant":"컨설턴트가 사분면 슬라이드를 만들었는데, 우리가 엉뚱한 칸에 들어가 있었어요.",
"lifecycle.odd_raccoon":"너구리가 그들의 하나뿐인 캐비닛에 이사 왔는데, 다른 통신사의 크로스 커넥트를 더 좋아하는 것 같아요.",
"lifecycle.odd_rdns":"그들 IP의 역방향 DNS가 customer-cheapskate-04로 되어 있었어요. 팀원 중 누군가 그걸 봤어요.",
"lifecycle.odd_space":"AI 네이티브, 블록체인 기반, 위성 우선 전략으로 피벗했는데, 우리 광섬유는 우주에 없어요.",
"lifecycle.odd_spreadsheet_cell":"구매팀의 새 규칙: 모든 공급업체 이름이 스프레드시트 셀 하나에 줄바꿈 없이 들어가야 해요.",
"lifecycle.odd_the_cloud":"모든 걸 클라우드로 옮긴대요. 그 클라우드는 두 블록 떨어진 랙이고, 우리가 연결해 주고 있어요. 아직 눈치 못 챘어요.",
