"link_panels.a_diplomatic_spat_has_closed_the":"외교 갈등으로 카타르 주변 국경이 닫혀서, 도하와 사우디아라비아나 UAE 사이의 모든 링크가 다운됐어요. 고칠 것도 없고, 외교에는 급행 작업도 없어요: 바다로 멀리 돌아가세요.",
