"long_tail.the_solomon_islands_incumbent_on":"솔로몬 제도의 기존 강자. 2020년에야 드디어 상륙한 케이블을 써요.",
"long_tail.the_telco_for_st_helena_ascension":"세인트헬레나, 어센션, 포클랜드의 통신사. 링크가 살아 있냐고요? 아마도요.",
