"long_tail.tonga_s_own_telco_lived_through":"통가의 토종 통신사. 하나뿐인 케이블을 끊어 버린 화산 폭발에서도 살아남아, 이젠 예비 위성을 챙겨 둬요.",
"long_tail.took_a_streaming_giant_to_court":"자기 고객이 요청한 트래픽 비용을 누가 내느냐로 스트리밍 거인을 법정에 세웠어요. 유료 피어링, 기가비트당 과금.",
