"loop.new_networks_on_the_map_this":"<b>지도에 새 네트워크가 생겼어요.</b><br>이번 업데이트로 아직 연결되지 않은 네트워크가 추가됐어요. {n}일 동안은 무료 임시 경로로 연결되니, 도달 범위가 하룻밤 새 줄지는 않아요. 기간이 끝나기 전에 피어링하거나 트랜짓을 구매하세요.",
