"meet_a_network.peer_with_the_tier_1_club_n":{"one":"Tier 1 클럽과 피어링하세요. 그들의 고객이 덤으로 따라와요. 이미 {n}개 네트워크가 피어를 통해 따라와요.","other":"Tier 1 클럽과 피어링하세요. 그들의 고객이 덤으로 따라와요. 이미 {n}개 네트워크가 피어를 통해 따라와요."},
