"modal_and_names.open":"열기 →",
"modal_and_names.our_signal_group_screenshots_chat":"Signal 그룹이에요. 다른 플레이어와 스크린샷을 나누고 피어링 정책을 두고 토론해요. 진짜보다 굴착기는 적어요.",
"modal_and_names.tell_us_on_github_a_short":"GitHub에서 알려 주세요. 버그 신고, 기능 아이디어, 밸런스, 번역을 위한 짧은 양식이 있어요. 하나도 빠짐없이 읽어요.",
"modal_and_names.the_real_thing_by_thomas_kj":"Thomas Kjær Aabo가 만든 진짜예요. Wi-Fi부터 해저 광섬유까지 패킷이 실제로 어떻게 이동하는지 확대하며 볼 수 있는 인터랙티브 지도로, 오늘날, 2010년, 1995년 모습을 보여 줘요. 이 게임은 그때그때 지어내지만, 그건 정확해요.",
"modal_and_names.the_real_thing_follow_a_packet":"진짜를 보세요. Wi-Fi부터 해저 광섬유까지 패킷을 따라가 봐요.",
"modals.lay_your_own_subsea_cable":"나만의 해저 케이블 부설…",
"modals.your_own_subsea_cable_level_n":"나만의 해저 케이블 <small>레벨 {n} 또는 Tier 1</small>",
"mphelp.boards_rank_traffic_with_players":"순위표는 최근 24시간 동안의 다른 플레이어와의 트래픽, 총 트래픽, POP, 하늘 위 파이, 고객 콘을 총량 또는 성장률로 순위를 매겨요. 돈은 절대 아니에요. 순위는 서버가 매기고, 게임이 가끔 한 줄씩 검증해요. 사람과 AI 플레이어는 함께 또는 따로 순위를 매길 수 있고, 지역, 홈 시장, 네트워크 연차 등으로 필터링할 수 있어요.",
"mphelp.deals":"거래",
"mphelp.deals_are_sealed_for_the":"모든 거래는 두 플레이어끼리만 봉인돼요. 서버는 전달만 할 뿐 내용을 읽을 수 없어요. 무엇을 제안했는지, 가격이 얼마인지, 왜 거절했는지도요. 모두에게 열린 컨소시엄 프로젝트만 공개돼요.",
"mphelp.for_their_first_30_days":"처음 30일 동안 신규 플레이어는 기존 네트워크에서 25% 할인된 가격으로 구매해요. 신규 플레이어와 거래하는 기존 네트워크는 신규 플레이어가 성장하면 일회성 멘토 보너스를 받아요: POP 10개, Tier 2, 또는 자체 트랜짓 고객 확보.",
"mphelp.how_multiplayer_works":"Multimode 작동 방식",
"mphelp.joining":"참여하기",
"mphelp.multiplayer_puts_other_people_s":"Multimode는 다른 사람들의 네트워크를 내 게임으로 가져와요. 모두 여전히 자기 기기에서 자기 게임을 하고, 서버는 게임 사이에 서명된 메모만 전달해요. 세이브별로 설정하며 완전히 선택 사항이에요.",
"mphelp.mute_a_network_and_it":"네트워크를 음소거하면 내 게임에서만 사라져요. 신고하면 서버 운영자가 살펴봐요. 운영자는 자기 서버에서 네트워크를 숨길 수 있고, 충분히 많은 서버가 제외에 투표하면 모든 곳에서 제외돼요. 투표는 공개되지 않아요. 누가 제외됐는지만 볼 수 있고, 그게 나라면 제시된 이유도 볼 수 있어요. 내 게임은 언제나 계속돼요.",
"mphelp.muting_reporting_and_exclusion":"음소거, 신고, 제외",
"mphelp.newcomers_and_mentors":"신규 플레이어와 멘토",
"mphelp.nothing_breaks_your_game_plays":"아무것도 망가지지 않아요. 게임은 계속되고, 내 행동은 대기열에 쌓였다가 나중에 전송되며, 진행 중인 거래도 유지돼요. 응답 없는 네트워크는 서서히 사라져요. 일주일이 지나면 트래픽이 다른 경로로 옮겨 가고, 약 5주가 지나면 통지와 함께 거래가 끝나요. 갑작스러운 청구서는 절대 없어요.",
"mphelp.peer_with_other_players":"다른 플레이어의 네트워크도 내 고객이 닿고 싶어 하는 곳이에요. 그들과 피어링하세요. 그들이 등록된 IX에서도 할 수 있어요. 그들에게서 트랜짓, PNI, IX 포트, 파장을 사거나, 용량을 맞교환하거나, 함께 컨소시엄 케이블을 지을 수도 있어요. 모든 네트워크는 정책과 가격을 공개하고, 조건에 맞는 요청은 상대가 자리에 없어도 자동으로 수락될 수 있어요. 돈은 세이브 사이를 오가지 않아요. 각 게임이 자기 쪽 장부만 기록해요.",
"mphelp.private_deals":"거래는 비공개예요",
"mphelp.servers_and_operators":"서버와 운영자",
"mphelp.servers_are_run_by_players":"서버는 플레이어가 운영해요. 서버마다 운영자가 한 명 이상 있고, 누구나 서버를 열 수 있어요. 일부 서버는 다른 서버와 동기화해서 내 서버 밖의 플레이어도 만날 수 있어요. 루킹 글래스에서 내 게임이 아는 모든 서버와 동기화 방식을 볼 수 있어요. 최대 네 곳까지 참여할 수 있어요.",
"mphelp.switch_on_play_with_others":"타이틀 화면에서 새 게임을 시작할 때 <b>다른 사람과 플레이</b>를 켜거나, 나중에 메뉴나 설정의 Multimode에서 참여하세요. 퍼즐, 시나리오, 샌드박스, '열린 문'은 싱글 플레이로 남아요. 네트워크 이름은 참여하는 모든 서버에 공개되니, 실명은 쓰지 않는 게 좋아요.",
"mphelp.when_a_server_is_down":"서버가 다운됐을 때",
"mphelp.your_multiplayer_identity_is_a":"네트워크의 Multimode 신원은 이 세이브에 보관된 개인 키예요. Multimode 시트의 <b>다른 기기로 옮기기</b>를 누르면 이 키가 담긴 파일 하나를 내려받아요. 그 파일만 있으면 누구든 내 네트워크 행세를 할 수 있으니, 절대 공유하거나 버그 신고에 첨부하지 마세요. 내보내기 파일과 공유 세이브에는 키가 절대 포함되지 않아요.",
