"networks.a_mobile_network_named_after_the":"건배 소리에서 이름을 딴 모바일 네트워크. 모든 5G 기지국에 건배!",
"networks.a_spanish_carrier_starring_in_every":"모든 중남미 시장에서 주연을 맡은 스페인 통신사. 적어도 다음 시장을 팔아 치우기 전까지는요.",
"networks.a_tiny_telco_in_a_country":"세계의 케이블이 상륙하는 나라의 작은 통신사. 가격도 그에 걸맞아요.",
"networks.africa_s_mobile_giant_in_a":"궤도에서도 보이는 노란색의 아프리카 모바일 거인. 이름과 달리 텅 빈(empty) 적은 한 번도 없어요.",
"networks.an_edge_cloud_that_is_despite":"이름과는 달리 꽤 빠른 엣지 클라우드.",
"networks.australia_s_big_one_g_day":"호주의 큰형님. 굿데이, 메가비트당 9달러예요. 아, 죄송, 기가비트요.",
"networks.australia_s_number_two_once_took":"호주의 2인자. 일상적인 업그레이드 한 번으로 나라 전체를 12시간 동안 오프라인으로 만든 적이 있어요.",
"networks.bay_area_fiber_with_an_old":"옛날식 태도를 지닌 베이 에어리어 광섬유. 오픈 피어링에, 전화는 진짜 사람이 받아요.",
"networks.beams_the_outback_online_from_550":"550 km 상공에서 아웃백을 온라인으로 연결하고, 결국 남들처럼 시드니 데이터 센터에 내려놓아요.",
"networks.bought_by_speedyloop_and_still":"Speedyloop에 인수됐는데, 청구서에 어느 이름을 넣을지 아직 정하는 중이에요.",
"networks.brazil_s_mobile_giant_very_much":"브라질의 모바일 거인. 아주 팔팔하게 살아 있어요.",
"networks.bridges_europe_and_asia_and":"유럽과 아시아를 잇고, 가끔은 BGP 테이블도 이어 버려요.",
"networks.cable_broadband_across_central":"중부 유럽 전역의 케이블 브로드밴드. 이따 고객센터 대기열에서 만나요.",
