"ops.mood_annie":"애니 씨는 가장 가까운 책상에서, 묻기도 전에 질문 세 개에 답해 줬어요.",
"ops.mood_broke":"{name} 씨는 다음 달 예산이 들어오면 살 쇼핑 목록을 준비해 뒀어요.",
"ops.mood_busy":"{name} 씨는 바쁜 한 주를 보내고 에너지 드링크를 세 캔째 마시고 있어요.",
"ops.mood_frozen":"{show} 동안 변경 동결이에요. {name} 씨는 손을 깔고 앉아 있고, 누가 그 손 위에 같이 앉아 달라고까지 부탁했어요.",
