"ops.mood_snag":"{name} 씨가 이상한 걸 발견해서, 그 지시를 일시 중지하고 메모를 붙여 뒀어요.",
"ops.mood_tracy":"트레이시 씨는 traceroute 세 번째 홉에 와 있어요. 아직 별표는 하나뿐이에요.",
"ops.no_cap":"제한 없음",
"ops.no_clock":"시계도, 근무 교대도 없어요. 이 규칙에서는 인턴이 일할 날짜가 없어요.",
"ops.o_caches":"무료 캐시 받기",
"ops.o_caches_d":"어떤 네트워크의 해당 도시 트래픽이 기준을 넘으면, 그 네트워크가 제공하는 무료 캐시를 모두 랙에 설치해요.",
"ops.o_decom":"작은 병렬 링크 정리",
"ops.o_decom_d":"두 도시 사이에 더 큰 링크가 개통되면, 더는 필요 없는 작은 파장 회선을 반납해요. 고객이 임대하거나 의존하는 회선은 절대 반납하지 않아요.",
"ops.o_fabric":"익스체인지 키우기",
"ops.o_fabric_d":"운영하는 익스체인지의 트래픽이 ‘여유’ 설정을 넘거나, 자리가 꽉 차서 가입을 기다리는 네트워크가 있으면 패브릭을 업그레이드해요. 패브릭이 클수록 트래픽을 더 많이 싣고, 유료 회원도 더 받을 수 있어요.",
"ops.o_ix":"모든 IX에서 피어링",
"ops.o_ix_d":"매주: 라우트 서버에 가입하고, 내 익스체인지 포트마다 피어링 의향이 있는 모든 회원에게 요청해요.",
"ops.o_optics":"광섬유 더 켜기",
"ops.o_optics_d":"뜨겁게 달아오른 다크 파이버에 광모듈을 추가하고, 새 광섬유는 인계받는 날 바로 켜요.",
"ops.o_optmod":"광모듈 현대화",
"ops.o_optmod_d":"여유가 있어도 켜져 있는 모든 광섬유를 더 새로운 광모듈로 바꿔요. 고른 모델이나, 각 광섬유에서 닿는 가장 빠른 모델로요. 작은 광모듈부터 한 채널씩 중단 없이 교체하고, 오래된 건 예비 선반에 둬요. 그 광섬유에서 더 많이 실어 나를 때만 교체해요.",
"ops.o_optup":"광전송 업그레이드",
"ops.o_optup_d":"꽉 차서 뜨겁게 돌아가는 광섬유, 또는 용량 시장 구매자들이 팔 수 있는 것보다 더 원하는 광섬유는 라인 시스템을 한 단계 키우거나, 가장 작은 채널을 더 큰 광모듈로 바꿔요 (기존 광모듈은 선반으로). 라인 시스템을 고르면, 더 작은 라인 시스템을 쓰는 모든 광섬유가 그걸로 올라가요. 라인 시스템 교체는 광섬유를 하루 동안 내리기 때문에, 트래픽이 우회할 수 있고 고객이 타고 있지 않은 곳에서만, 하룻밤에 하나씩 해요.",
"ops.o_pie":"크러스트 계속 채우기",
"ops.o_pie_d":"오래된 파이가 닳아도 크러스트가 꽉 차 있도록 발사를 예약해요: 공장 선반의 파이로, 첫 번째 빈 발사대에서, 시험 비행은 절대 안 해요. 비용은 크러스트 탭의 가격과 같아요.",
"ops.o_pni":"큰 곳과 PNI",
"ops.o_pni_d":"매주: 내 POP에 트래픽을 충분히 보내는, 의향 있는 모든 네트워크와 각 네트워크의 최소 크기로 PNI를 주문해요.",
"ops.o_ports":"피어링 여유 유지",
