"peering_desk.n_more_exchanges":{"one":"IX {n}곳 더","other":"IX {n}곳 더"},
"peering_desk.n_new_sessions_at_ix":{"one":"피어링 데스크: {ix}에서 새 세션 {n}개 ({pol}).","other":"피어링 데스크: {ix}에서 새 세션 {n}개 ({pol})."},
"peering_desk.n_new_sessions_at_ix_declined":{"one":"피어링 데스크: {ix}에서 새 세션 {n}개, {d}건 거절 ({pol}).","other":"피어링 데스크: {ix}에서 새 세션 {n}개, {d}건 거절 ({pol})."},
"peering_desk.n_requests_declined":{"one":"피어링 데스크: 요청 {n}건 거절 ({pol}).","other":"피어링 데스크: 요청 {n}건 거절 ({pol})."},
"peering_desk.open_desc":"요청하는 네트워크라면 누구든 세션을 받고, 라우트 서버도 작동해요.",
"peering_desk.open_to_all":"개방형",
"peering_desk.selective_desc":"IX의 작은 네트워크와 PeeringDB를 최신으로 유지하는 신참은 세션을 받고, 나머지는 조용히 거절돼요. 라우트 서버는 없어요. IX마다 원하는 네트워크에 직접 요청하세요.",
"peering_policy.a_new_vp_wants_to_monetise":"새로 온 부사장이 이 시장에서 \"상호접속을 수익화\"하고 싶어 해요.",
"peering_policy.already_reach_you_through_your":"이미 여기서 자기 트랜짓 사업자를 통해 연결되고 있고, 그걸로 충분하다고 생각해요.",
"peering_policy.moved_everything_in_this_city_to":"이 도시의 모든 연결을 PNI로 옮겼어요. PearingDB 페이지를 읽어 주세요. 40페이지 전부요.",
"peering_policy.not_accepting_new_peers_in_this":"지금은 이 지역에서 새 피어를 받지 않아요.",
"peering_policy.only_peers_over_pnis_in_this":"이 대도시권에서는 PNI로만 피어링해요. 대신 크로스 커넥트를 주문하세요.",
"peering_policy.only_peers_with_members_they_can":"1,500 km씩 헤어핀을 돌지 않고 닿을 수 있는 회원과만 피어링해요.",
"peering_policy.policy_no_remote_peers_be_in":"정책: 원격 피어 사절. 건물 안에 들어오시든가, 트랜짓 청구서에 들어오시든가.",
"peering_policy.price_war_in_city_ix_cut":"<b>{city}에서 가격 전쟁!</b><br>{ix}이(가) 회원들이 {rival}(으)로 빠져나가는 걸 막으려고 포트 가격을 10% 내렸어요. 청구서가 조금 가벼워졌어요.",
"peering_policy.region_frozen_while_they_renegotiate":"현지 기존 강자와 재협상하는 동안 이 지역은 동결됐어요.",
"peering_policy.remote_peering_is_a_last_resort":"<b>원격 피어링은 최후의 수단이에요.</b> 포트는 재판매업체를 거쳐 1.5배 가격에 오고, 포트의 80%만 실제로 내 것이며, 지연 시간은 패브릭을 타고, 패브릭 장애 한 번에 모든 세션이 끊기고, 선택적 피어링 네트워크 상당수는 원격 회원을 거절해요. 여기에 POP를 두는 게 나아요.",
"peering_policy.rival_is_poaching_de_kicks_members":"<b>{rival}이(가) {city}에서 DE-KICKS 회원을 빼 가고 있어요.</b><br>DE-KICKS는 \"프리미엄 상호접속의 가치\"에 관한 웨비나로 응수했어요. 가격은 그대로예요.",
"peering_policy.saw_your_session_come_in_over":"세션이 패브릭을 타고 들어오는 걸 보더니 \"여기서도 VXC 냄새가 나네요\"라고 했어요.",
"peering_policy.the_peering_coordinator_for_this":"이 도시의 피어링 담당자가 6개월 안식 휴가 중이에요.",
"peering_policy.their_ix_port_here_is_full":"여기 IX 포트가 다음 증설 때까지 꽉 찼대요. 곧이라고 약속은 하네요.",
"peering_policy.their_lawyers_are_reviewing_every":"법무팀이 이 나라의 피어링 계약서를 전부 검토하고 있어요. 또요.",
"peering_policy.their_pearingdb_entry_says_remote":"PearingDB 항목에 \"원격 피어링: 안 함 (진심임)\"이라고 적혀 있어요.",
"peering_policy.their_policy_here_says_ix_peering":"여기 정책에는 \"IX 피어링은 초대받은 경우만\"이라고 적혀 있어요. 초대받지 못했어요.",
"peering_policy.their_routers_in_this_city_are":"이 도시의 라우터가 \"용량 한계\"래요. 사실 아니에요.",
"peering_policy.tried_a_remote_peer_once_it":"원격 피어를 한 번 받아 봤는데, 제품 출시 중에 플래핑했대요. 두 번 다시는 안 한대요.",
