"pie_fix.fiber_h":{"one":"그곳에 착륙하는 궤도 고객 {n}곳이 {lack}만큼 못 받고 있어요. POP가 트래픽의 {sf}만 내보내고 있어요. 궤도는 문제없으니 {city}에서 나가는 링크나 트랜짓을 늘리세요.","other":"그곳에 착륙하는 궤도 고객 {n}곳이 {lack}만큼 못 받고 있어요. POP가 트래픽의 {sf}만 내보내고 있어요. 궤도는 문제없으니 {city}에서 나가는 링크나 트랜짓을 늘리세요."},
