"pie_fix.home_h":{"one":"그곳의 궤도 고객 {n}곳이 {lack}만큼 못 받고 있어요. {a}은(는) 트래픽을 자국 내 접시에만 착륙시키게 하는데, 그곳에 접시가 없어요. 하나 지어 주거나, 인시던트 카드에서 예외를 사세요.","other":"그곳의 궤도 고객 {n}곳이 {lack}만큼 못 받고 있어요. {a}은(는) 트래픽을 자국 내 접시에만 착륙시키게 하는데, 그곳에 접시가 없어요. 하나 지어 주거나, 인시던트 카드에서 예외를 사세요."},
"pie_fix.home_t":"{a}은(는) 데이터를 국내에 둬요",
"pie_fix.intro":"궤도에서 가득 찬 모든 것을 가득 찬 순으로, 해결 버튼과 함께 보여 줘요. 회색 버튼은 아래에 이유가 나와요.",
"pie_fix.nocrust_h":{"one":"궤도 고객 {n}곳이 {lack}만큼 못 받고 있어요. 지금 그 위를 지나는 크러스트 중 트래픽을 나르는 게 없어요 (커버리지, 폭풍 또는 안전 모드).","other":"궤도 고객 {n}곳이 {lack}만큼 못 받고 있어요. 지금 그 위를 지나는 크러스트 중 트래픽을 나르는 게 없어요 (커버리지, 폭풍 또는 안전 모드)."},
