"pie_fix.skyfull_h":{"one":"그곳에 착륙하는 궤도 고객 {n}곳이 {lack}만큼 못 받고 있어요. 접시엔 여유가 있지만, 그 위의 크러스트에 남은 여유가 없어요.","other":"그곳에 착륙하는 궤도 고객 {n}곳이 {lack}만큼 못 받고 있어요. 접시엔 여유가 있지만, 그 위의 크러스트에 남은 여유가 없어요."},
