"pie_fix.why_far":"{km} km 안에 이들을 착륙시킬 접시 안테나가 없고, 위쪽 크러스트에는 더 먼 곳으로 착륙시킬 레이저도 없어요",
"pie_fix.why_fiber":"이들의 트래픽은 {city}에 착륙하는데, 거기서 나가는 광섬유 용량이 부족해요 (파이 관제, 병목)",
"pie_fix.why_home":"{a}에서는 트래픽을 국내 접시 안테나에만 착륙시킬 수 있어요. 그곳에 하나 지으세요 (파이 관제, 병목)",
"pie_fix.why_nocrust":"이들 위의 크러스트 중 트래픽을 나르는 게 없어요. 파이를 더 발사하세요 (파이 관제, 크러스트)",
