"privacy.leaving":"나가기",
"privacy.no_account_no_email_no":"계정도, 이메일도, 쿠키도 없어요. 게임이 저장하는 것과 기기 밖으로 나가는 것을 모두 알려드릴게요.",
"privacy.on_seriesoftub_es_the_page":"seriesoftub.es에서는 페이지가 작은 방문자 카운터를 불러와요(jsDelivr에서 받아 stats.seriesoftub.es로 보고). 카운터는 페이지 주소, 이전 페이지, 창 너비, 페이지가 열려 있던 시간, 그리고 새 게임 시작이나 배지 획득 같은 게임 속 순간의 이름과 함께 페이지 조회 수를 세요. 쿠키를 만들지 않고 브라우저에 아무것도 저장하지 않아요. 이 카운터는 게임 제작자가 만든 ridiculytics로, 저희 서버에서 돌아가요. 데이터베이스도 없고 디스크에 아무것도 쓰지 않으며, 메모리에 누적 집계만 해요(페이지별, 유입 사이트의 호스트 이름, 국가, 브라우저, 운영체제, 기기 종류, 화면 크기 구분, 게임 순간별). IP 주소는 방문을 집계하는 동안 국가를 조회하는 데만 쓰이고 절대 저장되거나 기록되지 않아요. 순 방문자는 24시간마다 비밀값이 바뀌는 해시로 세기 때문에 날짜를 넘어 방문을 연결할 수 없어요. 다른 곳에 있는 게임 사본은 아무것도 보내지 않아요.",
"privacy.on_this_device":"이 기기에서",
"privacy.the_same_on_the_web":"웹의 이 페이지",
"privacy.the_visit_counter":"방문자 카운터",
"privacy.traffic_numbers_for_72_hours":"트래픽 수치는 72시간(그리고 가장 최근 수치), 거래는 30일, 네트워크 설명은 180일 동안 소식이 없을 때까지 보관해요. 시간은 5분 단위로 반올림해요. 네트워크에 대한 운영자 투표는 97일간 유지돼요.",
"privacy.what_servers_keep":"서버가 보관하는 것",
"privacy.what_servers_never_keep":"서버가 절대 보관하지 않는 것",
"privacy.what_the_game_keeps":"게임이 보관하는 것",
"privacy.what_the_game_keeps_and":"게임이 보관하고 보내는 것",
"privacy.when_you_join_a_server":"서버에 참여할 때",
"privacy.while_you_play":"플레이하는 동안",
"privacy.your_current_numbers_every_10":"게임이 열려 있고 수치가 바뀌었다면 10초마다 현재 수치(위와 같은 내용, 그 이상은 없음)를 보내요. 그래야 순위표에 지금 상황이 보이거든요. 서버는 이 수치를 디스크가 아닌 메모리에만 보관하고, 마지막 수신 후 15분이 지나면 잊어버려요.",
"privacy.your_game_sends_these_signed_records":"게임은 다음 서명된 기록을 보내요: 네트워크 이름, AS 번호, 게임 속 본거지 시장, 참여한 게임 날짜와 실제 날짜, POP 및 익스체인지 도시, 고객 수, 트래픽 수치와 트래픽 구성, 다른 플레이어 네트워크 각각과 주고받는 트래픽 양, Tier 1인지 Tier 2인지, 공개한 정책과 가격, 트랜짓을 누구에게서 사거나 누구에게 파는지(가격은 제외), 그리고 AI 에이전트가 플레이할 경우 AI 모델과 하네스. 거래는 상대 플레이어만 볼 수 있게 봉인되어 전송돼요. 다른 네트워크에 대해 보내는 신고(어떤 네트워크인지, 이유는 무엇인지)는 해당 서버 운영자에게 전달돼요. <b>내 국가 공유</b>가 켜져 있으면 실제 국가가 추가되며, 직접 끄기 전까지 켜져 있어요.",
"privacy.your_saves_settings_and_badges":"세이브, 설정, 배지, 진행 상황은 이 브라우저의 저장소에 남아요. 멀티모드에서는 네트워크의 개인 키(세이브 안에), 서버가 다른 네트워크에 대해 보내 준 정보(180일간 소식이 없으면 잊음), 그리고 가져온 운영자 키도 보관해요. 서버에 참여하거나 직접 세이브를 보내지 않는 한 아무것도 업로드되지 않아요.",
