"routescript.drain_a_pop_and_steer_around":"작업 전에 POP 하나를 비우고 그 POP의 링크 하나를 우회해요. 이름은 작업할 대상으로 바꾸세요.",
"routescript.during_an_attack_rtbh_the_target":"공격 중에 대상을 업스트림에서 블랙홀 처리해요(RTBH). 나머지는 모두 살지만, 규칙을 지울 때까지 대상은 먹통이에요.",
"routescript.every_gigabit_leaving_your_network_picks":"네트워크를 나가는 모든 기가비트는 출구를 하나 골라요: PNI, IX 포트, 트랜짓 포트. 그냥 두면 여유가 있는 가장 가까운 피어링으로 가고(같은 도시면 IX 포트보다 PNI 먼저), 어떤 피어링도 받아 줄 수 없을 때만 트랜짓으로 가요. RouteScript는 실제 라우터에서 local-pref, AS-path 프리펜딩, 유지보수 드레인이 하듯 이 선택을 바꿔요.",
"routescript.filled_in_from_your_network_as":"지금 네트워크 상태를 바탕으로 채웠어요. 하나 불러와서 읽어 보고, 검사한 다음 배포하세요.",
"routescript.for_a_ddos_rtbh_the_target":"DDoS 대응: 대상을 업스트림에서 블랙홀 처리하고 기업 고객을 우선해요. 그동안 대상은 먹통이니, 공격이 끝나면 지우세요.",
"routescript.from_this_load_on_spill_onto":"우회 단계: 최단 경로가 이만큼 차면, 넘치는 트래픽은 추가 지연이 이 밀리초 이하이고 같은 기준선 아래에 머무는 가장 좋은 우회로로 가요. 여러 단계를 쌓으면(80%에서 10 ms 이내, 90%에서 20 ms 이내) 링크가 뜨거워질수록 더 일찍, 더 멀리 우회해요.",
"routescript.great_question_here_is_a_production":"좋은 질문이에요! 실시간 트래픽에 딱 맞춘, 바로 프로덕션에 쓸 수 있는 스크립트예요. 꼼꼼하게 확인했어요.",
