"rules.rare_outages_no_ddos_pnis_at_once":"드문 장애, DDoS 없음, 카오스 몽키 없음, 콘퍼런스 없음. PNI는 주문하는 순간 개통되고, 해저 케이블 절단은 케이블선 없이도 복구되고, 구축은 며칠이면 끝나고, 가격은 그대로예요. 참을성 있는 고객, 조용한 알림, 그리고 게임 오버 대신 구제 대출.",
