"sales.auto":"대신 계약해 줘요",
"sales.auto_ceo":"{name}이(가) 지금 네트워크로 감당할 수 있는 제안에 서명해요. 체험은 하루 하나. 최저가 미만 제안도 거절하지만, 가끔은 이미 악수를 해 버린 뒤예요.",
"sales.auto_eng":"{name}이(가) 지금 네트워크로 감당할 수 있는 제안에 서명해요. 서명 전에 하나씩 네트워크에서 먼저 시험해 보고(하루 하나), 최저가보다 싼 제안은 거절해요.",
"sales.auto_shark":"{name}이(가) 커미션만 낼 수 있다면 들어오는 제안마다 약속까지 몽땅 얹어서 즉시 서명해요. 최저가보다 싼 제안은 거절해요.",
"sales.by_hand":"영업 담당이 없어서 모든 거래에 직접 서명해야 해요. 영업 담당을 고용하거나 CEO에게 맡기면 대신 계약해 줘요.",
"sales.ceo_d":"무료이고, 자신감도 넘쳐요. 두어 달마다 골프장에서 30% 할인으로 큰 계약을 따오는데, 아무도 확인하지 않은 약속이 붙어 있는 경우가 많고, 가끔은 거절한 제안에 서명해 버리기도 해요. 주관이 뚜렷해요. 해고할 수 없어요.",
"sales.ceo_golf":"CEO가 골프장에서 {name}와(과) 계약했어요: {city}에 {bw}, {price}/월, 정가에서 30% 할인.",
"sales.ceo_golf_skip":"창업자가 골프를 건너뛰었어요: 시장이 너무 불안하대요. CEO는 혼자 쳤고, 궤도 계약은 하나도 못 했어요.",
"sales.ceo_golf_sky":"CEO와 창업자가 골프장에서 {name}와(과) 계약했어요: {city} 상공 궤도에 {bw}, {price}/월, 정가에서 {p} 할인.",
"sales.ceo_n":"누구보다 영업을 잘하는 CEO",
"sales.ceo_override":"{name}을(를) 거절했는데, CEO가 이미 악수를 해 버렸어요. 이제 고객이에요.",
"sales.ceo_promised":"이것도 약속했대요: {req}.",
"sales.ceo_s":"CEO",
"sales.ceo_say_airport":"방금 착륙했어. 계약은 못 했지만 라운지 와이파이 느낌이 아주 좋았어.",
"sales.ceo_say_blockchain":"라우팅 테이블을 블록체인에 올리는 건 생각해 봤나?",
"sales.ceo_say_golf":"최고의 거래는 9번 홀에서 나와. NOC도 골프 좀 쳐야 해.",
"sales.ceo_say_mbps":"왜 기가비트로 팔지? 메가비트가 더 많아 보이잖아.",
"sales.ceo_say_napkin":"다음 거래 가격은 냅킨에 적어 놨어. 세부 사항은 엔지니어링이 알아서 하겠지.",
"sales.ceo_say_synergy":"우린 대역폭을 파는 게 아니야, 시너지를 파는 거지. 그거 웹사이트에 올려.",
"sales.ceo_says":"CEO: “{say}”",
"sales.ceo_sky":"궤도: 골프 두 번에 한 번은 창업자와 함께 쳐서, 감당할 수 있는 가장 큰 궤도 계약을 30% 할인으로 따와요. 시장이 불안하면 손해예요: 궤도 가격이 떨어지고, 아주 불안하면 골프 자체를 안 쳐요.",
