"sales.decline_below":"거절 기준",
"sales.desk":"영업 데스크",
"sales.eng_booked":"{name}이(가) {city}에서 열리는 {conf}에 등록해 뒀어요({cost}). 목걸이 명찰은 이미 받아 왔대요.",
"sales.eng_desc":"네트워크 엔지니어 출신으로, 지금은 모든 NOG의 명찰을 갖고 있어요. 매번 등록해 주고(티켓값은 내셔야 해요), 중소 규모 계약을 꾸준히 가져오지만 정말 큰 건은 못 해요. 네트워크가 실제로 할 수 있는 것만 팔아서 고객이 떠나지 않아요. 너드들은 데이브를 좋아해요. 가격 협상은 젬병이에요. 정말 큰 건은 그래도 직접 연락이 와요. 그건 직접 계약하세요.",
"sales.eng_n":"영업맨이 된 엔지니어",
"sales.eng_s":"데이브",
"sales.eng_sky":"궤도: 지상국 안테나에 여유가 있는 곳에서만 팔고, 그 고객들은 너드들처럼 오래 남아요.",
