"sales.p_ren":"가격 협상 응대",
"sales.p_sign":"계약 서명",
"sales.ren":"갱신 가격 협상",
"sales.ren_ceo":"{name}은(는) 고객의 가격 협상이 시작되고 사흘 뒤 골프장에서 답해요: 계약 기간을 두 배로 늘리는 대신 요청보다 더 큰 할인, 아니면 바로 수락, 아니면 고객이 떠나 버리는 싸움.",
"sales.ren_ceo_fight":"{name}이(가) {cust}에게 자기한테 가격 협상하는 사람은 없다고 했어요. 고객은 떠났어요.",
"sales.ren_ceo_golf":"{name}이(가) 골프장에서 {cust} 건을 정리했어요: {price}/월, 요청보다도 싸게, {date}까지 고정.",
"sales.ren_ceo_yes":"{name}이(가) 누가 확인하기도 전에 {cust}에게 수락해 버렸어요: {price}/월.",
"sales.ren_eng":"{name}은(는) 고객의 가격 협상이 시작되고 사흘 뒤에 답해요. 기술 좋아하는 고객은 네트워크 구성도와 함께 오후를 보내고 대개 시장 가격으로 갱신해요. 나머지 고객은 요청한 할인을 받아요. 아무도 떠나지 않아요.",
"sales.ren_eng_cave":"{name}이(가) {cust}에게 요청한 할인을 해 줬어요: {price}/월. 계속 남아요.",
"sales.ren_eng_tech":"{name}이(가) 오후 내내 {cust}의 엔지니어들에게 네트워크를 구석구석 보여 줬어요. 할인 없이 {price}/월로 갱신해요.",
"sales.ren_mid":"{name}이(가) {cust}와(과) 중간에서 합의했어요: {price}/월.",
"sales.ren_shark":"{name}은(는) 고객의 가격 협상이 시작되고 사흘 뒤에 답하고, 아무것도 양보하지 않아요: 대부분 기존 가격으로 갱신하고 새 약속이 붙는 경우도 많아요. 그리고 아낀 금액의 한 달 치를 청구해요. 떠나는 고객도 있는데, 기술 좋아하는 고객일수록 그래요.",
"sales.ren_shark_hold":"{name}이(가) {cust}에게 가격은 가격이라고 했어요. {price}/월로 갱신했고, 지켜 낸 대가로 {fee}을(를) 청구해요.",
"sales.ren_shark_walk":"{name}이(가) {cust}에게 강하게 나갔다가, 고객이 떠나 버렸어요.",
"sales.ren_when":"먼저 답하지 않으면 {name}이(가) {date}에 답해요.",
"sales.shark_d":"가장 큰 계약을 25% 더 비싸게 따오고, 계약마다 한 달 치를 커미션으로 챙겨요. 과대 영업: 절반은 네트워크가 아직 지키지 못하는 약속이 붙어 있고, 그런 고객은 더 빨리 떠나요. 너드는 무시해요: 기술 고객 없음, 미팅 없음, 피어링 담당자들은 트래픽을 25% 더 요구해요. 가격 협상은 대부분 이겨요.",
"sales.shark_n":"상어",
"sales.shark_s":"채드",
"sales.shark_sky":"궤도: 항공사와 크루즈 선사에 먼저 전화해서 가장 큰 용량을 25% 더 비싸게 팔고, 절반에게는 아직 있지도 않은 하늘 전체 커버리지를 약속해요. 실제로 갖출 때까지 불평이 이어져요.",
"sales.vp_arrived":"영업 VP가 출근했고, CEO는 전략 업무로 돌아갔어요. 영업 데스크가 비었으니 누군가를 고용하세요.",
"sales.vp_asked":"이사회가 점심 먹고 나서 동의했어요. 영업 VP는 {n}일 뒤에 출근하고, 그때까지는 CEO가 계속 영업해요.",
"sales.vp_coming":"{n}일 뒤에 영업 VP가 넘겨받아요.",
"sales.w_anyway":{"one":"그중 한 건은 결국 계약","other":"그중 {n}건은 결국 계약"},
