"save.that_network_went_bankrupt_it_cannot":"그 네트워크는 파산했어요. 되살릴 수는 없고, 애도할 수만 있어요.",
"save.that_save_has_a_pop_in":"이 저장 파일에는 이 버전이 모르는 도시({city})에 POP가 있어요.",
"save.this_browser_is_not_letting_the":"<b>게임이 저장되지 않고 있어요.</b> 이 브라우저가 게임의 데이터 저장을 막고 있어요(시크릿 창이거나 사이트 데이터가 꺼져 있어요). 네트워크를 지키려면 저장 파일을 내보내세요.",
"save.this_file_carries_a_multimode_identity":"이 파일에는 네트워크의 멀티모드 신원 정보가 들어 있어요. {servers}에서 플레이하던 네트워크예요. 오프라인 상태로 불러와지니, 불러온 뒤 멀티모드에서 그 서버들에 다시 접속하세요. 아는 서버일 때만요.",
"save.your_network_is_too_big_to":"<b>게임이 저장되지 않고 있어요.</b> 네트워크가 이 브라우저의 저장 공간보다 커졌어요. 지금 저장 파일을 내보내서 보관하세요. 그게 백업이에요.",
