"scenarios.1_6t_on_every_hop_from":"마이애미에서 마드리드까지, 리스본에서 라고스까지 모든 홉이 1.6T, 그리고 100 Gbps 처리",
"scenarios.90_days_in_a_row_with":"90일 연속 수요의 99.5% 처리",
"scenarios.99_reach_and_150_gbps_served":"도달률 99%, 150 Gbps 처리",
"scenarios.a_path_from_cape_town_to_cairo_lagos":"케이프타운에서 카이로, 라고스, 나이로비까지 자체 네트워크 경로, 그리고 150 Gbps 처리",
"scenarios.a_path_from_los_angeles_to":"로스앤젤레스에서 시드니까지 모든 홉이 1.6T인 경로, 로스앤젤레스에서 도쿄까지 경로, 그리고 150 Gbps 처리",
"scenarios.a_path_from_marseille_to_singapore":"마르세유에서 싱가포르까지 경로, 그리고 아시아와 나머지 네트워크 사이 30일 연속 80 Gbps",
"scenarios.amsterdam_hosting_capital_of_europe":"유럽의 호스팅 수도 암스테르담, 봇넷 성수기. 지구상의 모든 스마트 토스터, 베이비 모니터, 패치 안 된 냉장고가 편을 골랐는데, 우리 편은 아니에요. 며칠마다 공격 트래픽이 몰려오고, 테라비트급도 점점 늘어나요. 그 와중에 다른 것들도 계속 고장 나요. 큰 장비가 잠금 해제된 상태로 시작하는데, 꼭 필요할 거예요.",
"scenarios.broadband_in_sydney_melbourne_served":"시드니, 멜버른, 브리즈번, 애들레이드, 퍼스에 브로드밴드, 서로 다른 해외 케이블 두 개, 그리고 500 Gbps 처리",
"scenarios.cape_to_cairo":"케이프에서 카이로까지",
"scenarios.cape_town_build_a_network_across":"케이프타운. 아프리카를 가로지르는 네트워크를 만드세요. 국경마다 따로 허가가 필요하고, 발전기도 네트워크의 일부예요.",
"scenarios.cogentle_and_goggle_are_not_speaking":"Cogentle과 Goggle이 말을 안 섞어요. 이번엔 영원히요. 배짱이 있다면 싼 트랜짓을 사 보세요.",
"scenarios.connect_panama_city_to_bogota_lima":"보고타, 리마, 산티아고, 상파울루를 파나마시티와 연결, 그리고 150 Gbps 처리",
"scenarios.deliver_carnaval_in_full":"카니발을 빠짐없이 전송",
"scenarios.every_cable_through_the_red_sea":"홍해를 지나는 모든 케이블이 끊겼고, 이집트로 가는 홉도 끊겼어요. 그래도 마르세유와 싱가포르를 연결하세요: 아프리카를 돌아가든, 육로로 가든, 지구 반대편으로 돌아가든.",
"scenarios.every_ix_is_run_by_de":"모든 IX를 DE-KICKS가 운영",
"scenarios.eyeballs_grow_50_faster":"개인 사용자 50% 더 빠르게 증가",
"scenarios.fibre_to_the_basement":"지하실까지 광섬유",
"scenarios.gangnam_style_peering":"강남 스타일 피어링",
"scenarios.hold_20_floods_5_terabit":"공격 20회 버티기(5회는 1 Tbps 초과): 대상마다 97% 이상, 다른 누구도 피해 없이",
"scenarios.honolulu_in_the_middle_of_the":"태평양 한가운데 호놀룰루. 아메리카, 아시아, 호주를 잇는 케이블은 너무 길어서 파장 하나에 400G나 800G밖에 못 실어요. 섬에서 빛을 멈추고 새로 쏘면 홉마다 짧아지고 빨라져요. 1.6T 장비가 잠금 해제된 상태로 시작해요.",
"scenarios.mid_atlantic_accent":"대서양 한복판 사투리",
"scenarios.only_spatzle_ix":"오직 Spätzle-IX뿐",
"scenarios.order_and_progress":"질서와 진보",
"scenarios.ponta_delgada_azores_lisbon_lagos":"대서양 중간, 아조레스 제도의 폰타델가다. 플로리다에서 스페인까지는 1.6T 파장으로는 너무 멀어요: 곧장 건너면 1.2T밖에 못 실어요. 중간의 섬들에 상륙해 빛을 새로 쏘면 모든 홉이 1.6T 이상으로 달려요. 리스본에서 라고스까지는 한 번에 1.6T가 되지만 비싸요: 카나리아 제도를 거치는 게 더 싸요. 1.6T 장비가 잠금 해제된 상태로 시작해요.",
"scenarios.ports_on_15_ix_brrr_exchanges_backbone":"백본이 상파울루와 연결된 IX.brrr 익스체인지 15곳(그중 한 곳은 마나우스)에 포트, 그리고 200 Gbps 처리",
"scenarios.reach_50_of_the_internet_and":"인터넷의 50%에 도달하고 300 Gbps 처리",
"scenarios.red_sea_crisis":"홍해 위기",
"scenarios.rio_from_scratch_carnaval_starts_in":"맨땅에서 시작하는 리우. 카니발이 90일 뒤에 시작되고, 닷새 내내 400 Gbps가 필요해요. 전 세계가 지켜보고 있어요.",
"scenarios.sandbox_mode_a_billion_dollars_chaos":"<b>샌드박스 모드</b><br>10억 달러와 모든 잠금 해제. 카오스: {chaos}. 늘 꿈꾸던 인터넷을 만드세요. 여분의 굴착기도 챙겨 두시고요.",
"scenarios.sandbox_mode_a_billion_dollars_every":"<b>샌드박스 모드</b><br>10억 달러, 모든 잠금 해제, 그리고 아무것도 고장 나지 않아요. 늘 꿈꾸던 인터넷을 만드세요.",
"scenarios.sao_paulo_brazil_is_a_continent":"상파울루. 브라질은 하나의 대륙이에요: IX.brrr 익스체인지 40곳, 지역 ISP(provedores) 수천 곳, 그리고 북쪽과의 사이를 가로막은 아마존.",
"scenarios.seoul_sender_pays_d":"발신자 부담의 도시, 서울. 통신사가 한국으로 전달하는 1 Gbps마다 트랜짓 요금에 더해 발신자 부담 요금이 붙어요. 3대 기존 강자는 유료 PNI로만 접속하고, 가정용 기가 인터넷은 비빔밥 한 그릇 값에 팔리고, 한국 사용자는 1밀리초도 놓치지 않아요. 도쿄 트랜짓은 싸요. 고객들이 그 거리를 참아 준다면요.",
"scenarios.seoul_sender_pays_goal":"{g} Gbps 처리, 서울 서비스 품질 양호({q}%), 도달률 99%, 월간 흑자",
"scenarios.shark_season_subsea_cuts_twice_as":"상어 철: 해저 케이블 절단 확률 두 배",
"scenarios.start_in_panama_city_nothing_crosses":"파나마시티에서 시작해요. 다리엔 갭은 육로로 건널 수 없고, 나머지 길은 전부 안데스산맥이 가로막고 있어요.",
"scenarios.start_in_stuttgart_where_nobody":"아무도 트랜짓을 팔지 않는 슈투트가르트에서 시작해요. 피어링, PNI, 캐시, 자체 광섬유만으로 인터넷에 닿으세요. 트랜짓은 어디에서도, 절대로 없어요.",
"scenarios.start_with_only_100k":"단 $100k로 시작",
"scenarios.sydney_2013_the_toilet_paper_group":"2013년 시드니. Toilet Paper Group이 아파트 지하실까지 자체 광섬유를 깔자, 국가 네트워크는 체리피킹이라며 울상이었어요. 이제 우리 차례예요: Nearly Broadband Network는 건너뛰고, 부담금을 내고, 먼저 도착하세요.",
"scenarios.tallinn_nobody_sells_transit_anchors":"아무도 트랜짓을 팔지 않는 탈린: 인터넷은 바다 건너에 있어요. 발트해 케이블 위로 배들이 닻을 끄는 일이 평소의 세 배예요.",
"scenarios.the_cogentle_spat":"Cogentle 말다툼",
"scenarios.transit_costs_30_more":"트랜짓 비용 30% 증가",
