"scenarios.weekly_key":"주간 {key}",
"scenarios.welcome_name_the_ripe_ncc_assigned":"<b>환영해요, {name}!</b><br>RIPE NCC가 AS{asn}을(를) 할당했어요. 첫 라우터가 {city}에서 웅웅 돌아가고 있어요.",
